SELECT c.volume_id, c.document_id, substr(c.header,1,140) FROM document_cache c WHERE (c.header LIKE '%corrupt%' OR c.header LIKE '%bribe%' OR c.header LIKE '%graft%' OR c.header LIKE '%scandal%' OR c.header LIKE '%kickback%' OR c.header LIKE '%payoff%' OR c.header LIKE '%embezzl%' OR c.header LIKE '%Foreign Corrupt%' OR c.header LIKE '%questionable payments%') AND c.is_front_matter=0 AND c.is_editorial_note=0 ORDER BY 1,2;
